/*Table structure for table `member` */

DROP TABLE IF EXISTS `member`;

CREATE TABLE `member` (
  `mb_fid` int(11) NOT NULL AUTO_INCREMENT,
  `mb_uid` varchar(50) NOT NULL,
  `mb_pwd` varchar(50) NOT NULL,
  `mb_level` int(11) NOT NULL,
  `mb_emp_fid` int(11) NOT NULL,
  `mb_nickname` varchar(50) NOT NULL,
  `mb_user` varchar(500) NOT NULL,
  `mb_money` int(11) unsigned NOT NULL,
  `mb_point` int(11) unsigned NOT NULL,
  `mb_time_join` datetime NOT NULL,
  `mb_time_last` datetime NOT NULL,
  `mb_ip_last` varchar(30) NOT NULL,
  `mb_game_pb_ratio` varchar(6) NOT NULL,
  `mb_state_active` int(11) NOT NULL,
  `mb_state_delete` int(11) NOT NULL,
  `mb_state_print` int(11) NOT NULL,
  `mb_limit_round` int(11) NOT NULL,
  `mb_limit_single` int(11) NOT NULL,
  `mb_limit_mix` int(11) NOT NULL,
  PRIMARY KEY (`mb_fid`)
) ENGINE=InnoDB AUTO_INCREMENT=48 DEFAULT CHARSET=utf8mb4;

